    {label:'В обработке',value:orders.filter(o=>o.status==='processing').length,delta:'+8,2%',icon:Clock,kind:'processing',foot:'ожидают вашего внимания',bars:[24,36,31,46,36,58,47,40,57,50,68,59,77,68]},
    {label:'В доставке',value:orders.filter(o=>o.status==='shipping').length,delta:'+6,4%',icon:Truck,kind:'shipping',foot:'уже на пути к клиентам',bars:[20,30,24,35,43,34,47,53,45,62,50,70,60,80]},
    {label:'Выручка',value:money(orders.filter(o=>o.paid && o.status"'!=='"'cancelled').reduce((a,o)=>a+o.amount,0)),delta:'+18,6%',icon:CircleCheck,kind:'completed',foot:'по оплаченным заказам',bars:[20,28,35,30,42,37,49,46,58,64,58,73,68,85]},
  ];
  return <div className=\"stats-grid\">{metrics.map(m=><div className={"'`stat-card ${m.kind}`} key={m.label}><div className="stat-top"><span>{m.label}</span><span className="stat-icon"><Icon data={m.icon} size={17}/></span></div><div className="stat-middle"><Text variant="header-1" className="stat-number">{m.value}</Text><span className="trend"><Icon data={ArrowUpRight} size={13}/>{m.delta}</span></div><div className="stat-bottom"><span>{m.foot}</span><div className="spark-bars" aria-hidden="true">{m.bars.map((height,i)=><i key={i} style={{height:`${height}%`}}/>)}</div></div></div>)}</div>;
}
export function App() {
  const [compact,setCompact] = useState(()=>stored('"'orbit-compact',window.innerWidth<760));
