ing-1);}.selection-bar>span{width:100%;}.users-grid{grid-template-columns:1fr;}.users-panel,.settings-panel{padding:var(--g-spacing-4);}.section-toolbar{flex-direction:column;align-items:stretch;}.section-toolbar .g-text-input{max-width:none;}.app-modal{padding:var(--g-spacing-5);}.toast{font-size:11px;bottom:var(--g-spacing-4);width:max-content;}.notifications-panel{width:260px;}}
