.empty-state {display:flex;flex-direction:column;align-items:center;gap:var(--g-spacing-3);padding:var(--g-spacing-10);color:var(--g-color-text-secondary);font-size:12px;}
.toast {position:fixed;bottom:var(--g-spacing-6);left:50%;transform:translateX(-50%);z-index:10000;display:flex;align-items:center;gap:var(--g-spacing-3);max-width:calc(100vw - 32px);padding:var(--g-spacing-3) var(--g-spacing-4);background:var(--g-color-base-background);border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-l);box-shadow:0 8px 32px var(--g-color-sfx-shadow);font-size:12px;animation:toast-in .2s ease-out;}
