.notification-icon {color:var(--g-color-text-brand);background:var(--g-color-base-selection);padding:var(--g-spacing-3);border-radius:var(--g-border-radius-m);display:flex;}
.users-panel,.settings-panel {background:var(--g-color-base-background);border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-l);padding:var(--g-spacing-6);}
.section-toolbar {display:flex;justify-content:space-between;gap:var(--g-spacing-4);align-items:center;margin-bottom:var(--g-spacing-6);}
